 17→	import BoardColumnComponent from '$lib/components/board/BoardColumn.svelte';
 18→	import ActiveFleetRow from '$lib/components/board/ActiveFleetRow.svelte';
 19→	import TaskDetailModal from '$lib/components/board/TaskDetailModal.svelte';
 20→	import BoardSkeleton from '$lib/components/board/BoardSkeleton.svelte';
 21→	import {
 22→		createSessionState,
 23→		processTextChunk,
 24→		type FleetSessionState,
 25→	} from '$lib/components/board/fleet-buffer';
 26→	import LayoutGrid from '@lucide/svelte/icons/layout-grid';
 27→	import List from '@lucide/svelte/icons/list';
 28→	import { Button } from '$lib/components/ui/button';
 29→	import { base } from '$app/paths';
 30→
 31→	let tasks = $state<TaskSummary[]>([]);
 32→	let columns = $state<BoardColumn[]>([]);
 33→	let loading = $state(true);
 34→	let error = $state('');
 35→	let agentStatus = $state<AgentDispatchStatus | null>(null);
 36→
 37→	// AC: @ui-task-board ac-4 — Buffered output state per agent session
 38→	let sessionStates = $state<Record<string, FleetSessionState>>({});
 39→
 40→	// Derived: output lines per session (for ActiveFleetRow)
 41→	let agentOutputLines = $derived<Record<string, string[]>>(
 42→		Object.fromEntries(
 43→			Object.entries(sessionStates).map(([id, s]) => [id, s.lines])
 44→		)
 45→	);
 46→
 47→	// AC: @ui-task-board ac-4 — Lookup map: task_ref (@ULID or @slug) → title
 48→	let taskTitles = $derived(
 49→		Object.fromEntries(
 50→			tasks.flatMap((t) => {
 51→				const entries: [string, string][] = [
 52→					[`@${t._ulid}`, t.title]
 53→				];
 54→				for (const slug of t.slugs) {
 55→					entries.push([`@${slug}`, t.title]);
 56→				}
 57→				return entries;
 58→			})
 59→		)
 60→	);
 61→
 62→	// Detail modal state
 63→	let modalOpen = $state(false);
 64→	let selectedTaskRef = $state<string | null>(null);
 65→
 66→	// Track last processed URL ref to avoid infinite loops
 67→	let lastProcessedRef = $state('');
 68→
 69→	$effect(() => {
 70→		// Re-derive columns whenever tasks change
 71→		columns = distributeToColumns(tasks);
 72→	});
 73→
 74→	// AC: @ui-task-board ac-5 — Load board when project is ready and reload on project change
 75→	// Gates on isProjectInitialized() to prevent loading with wrong/missing project context.
 76→	// Replaces the old onMount+$effect pattern that could race with project resolution.
 77→	$effect(() => {
 78→		const version = getProjectVersion();
 79→		const ready = isProjectInitialized();
 80→		if (!ready) return;
 81→		loadBoard();
 82→	});
 83→
 84→	// Open task detail from URL param
 85→	$effect(() => {
 86→		const urlRef = $page.url.searchParams.get('ref');
 87→		if (urlRef && urlRef !== lastProcessedRef) {
 88→			lastProcessedRef = urlRef;
 89→			selectedTaskRef = urlRef;
 90→			modalOpen = true;
 91→		}
 92→	});
 93→
 94→	async function loadBoard() {
 95→		loading = true;
 96→		error = '';
 97→		try {
 98→			const [taskResponse, statusResponse] = await Promise.all([
 99→				fetchTasks({ limit: 500 }),
100→				fetchAgentStatus().catch(() => null)
101→			]);
102→			tasks = taskResponse.items;
103→			agentStatus = statusResponse;
104→		} catch (err) {
105→			error = err instanceof Error ? err.message : 'Failed to load board';
106→		} finally {
107→			loading = false;
108→		}
109→	}
110→
111→	function handleCardClick(task: TaskSummary) {
112→		selectedTaskRef = task._ulid;
113→		modalOpen = true;
114→	}
115→
116→	function handleTaskUpdated() {
117→		loadBoard();
118→	}
119→
120→	// AC: @ui-task-board ac-5 — WebSocket real-time updates
121→	function handleTaskUpdate(event: BroadcastEvent) {
122→		loadBoard();
123→	}
124→
125→	// AC: @ui-task-board ac-4 — Refresh agent status on agent events
126→	function handleAgentUpdate(event: BroadcastEvent) {
127→		// AC: @ui-task-board ac-4 — Buffer text chunks into complete lines
128→		if (event.event === 'agent_text_chunk' && event.data?.session_id && event.data?.text) {
129→			const sessionId = event.data.session_id as string;
130→			const text = event.data.text as string;
131→			const current = sessionStates[sessionId] ?? createSessionState();
132→			sessionStates[sessionId] = processTextChunk(current, text);
133→			return;
134→		}
135→
136→		// Invocation lifecycle events — refresh status and clean up stale state
137→		fetchAgentStatus()
138→			.then((status) => {
139→				agentStatus = status;
140→				// Clean up session states for sessions no longer active
141→				const activeSessions = new Set(
142→					status.active_invocations.map((inv) => inv.session_id)
143→				);
144→				for (const sessionId of Object.keys(sessionStates)) {
145→					if (!activeSessions.has(sessionId)) {
146→						delete sessionStates[sessionId];
147→					}
148→				}
149→			})
150→			.catch(() => {});
151→	}
152→
153→	// Polling for agent elapsed time updates
154→	let agentPollTimer: ReturnType<typeof setInterval> | undefined;
155→
156→	onMount(() => {
157→		// AC: @ui-task-board ac-5 — Subscribe to task and agent updates
158→		subscribe(['tasks', 'agents']);
159→		on('tasks', handleTaskUpdate);
160→		on('agents', handleAgentUpdate);
161→
162→		// Poll agent status every 5s for elapsed time updates
163→		agentPollTimer = setInterval(() => {
164→			fetchAgentStatus()
165→				.then((status) => {
166→					agentStatus = status;
167→				})
168→				.catch(() => {});
169→		}, 5000);
170→	});
171→
172→	onDestroy(() => {
173→		off('tasks', handleTaskUpdate);
174→		off('agents', handleAgentUpdate);
175→		unsubscribe(['tasks', 'agents']);
176→		if (agentPollTimer) clearInterval(agentPollTimer);
177→	});
178→</script>
