195→				class="bg-accent"
196→				title="Board view"
197→				aria-pressed="true"
198→			>
199→				<LayoutGrid class="size-4" />
200→			</Button>
201→			<a href="{base}/tasks" title="List view">
202→				<Button variant="ghost" size="icon-sm" aria-pressed="false">
203→					<List class="size-4" />
204→				</Button>
205→			</a>
206→		</div>
207→	</div>
