222→			<LayoutGrid class="size-12 text-muted-foreground/30 mb-4" />
223→			<h2 class="text-lg font-medium text-muted-foreground mb-1">No tasks yet</h2>
224→			<p class="text-sm text-muted-foreground">
225→				Create tasks using <code class="bg-muted px-1 rounded text-xs">kspec task add</code>
226→			</p>
227→		</div>
228→	{:else}
229→		<!-- AC: @ui-task-board ac-4 — Active Fleet Row -->
230→		<div class="px-6 pt-4">
231→			<ActiveFleetRow status={agentStatus} outputLines={agentOutputLines} {taskTitles} />
232→		</div>
233→
234→		<!-- AC: @ui-task-board ac-1 — Kanban Columns -->
235→		<div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-4 p-6 pt-2 flex-1 min-h-0" data-testid="board-columns">
236→			{#each columns as column (column.id)}
237→				<BoardColumnComponent {column} onCardClick={handleCardClick} />
238→			{/each}
239→		</div>
240→	{/if}
241→</div>
242→
243→<!-- AC: @ui-task-board ac-3, ac-6 — Detail Modal -->
244→<TaskDetailModal
245→	bind:open={modalOpen}
246→	bind:taskRef={selectedTaskRef}
247→	onTaskUpdated={handleTaskUpdated}
