      filtered = filtered.filter((task) => statusFilters.includes(task.status));
    }

    // ... other filters (type, tag, automation, plan)

    // AC: @api-contract ac-4 - Pagination
    const total = filtered.length;
    const offset = Number(query.offset) || 0;
    const limit = Number(query.limit) || total;  // KEY: If no limit, returns ALL

    const paginated = filtered.slice(offset, offset + limit);

    // Return items with critical fields:
    // - _ulid, slugs, title, type, status, priority
    // - spec_ref, tags, depends_on, automation
