### 4. **Column Distribution Logic** (board-utils.ts Lines 74-136)
```typescript
export function distributeToColumns(tasks: TaskSummary[]): BoardColumn[] {
  const backlog: TaskSummary[] = [];
  const ready: TaskSummary[] = [];
  const inProgress: TaskSummary[] = [];
  const review: TaskSummary[] = [];
  const done: TaskSummary[] = [];

  // Switch on task.status to distribute:
  for (const task of tasks) {
    switch (task.status) {
      case 'pending': {
        const auto = task.automation;
        if (auto === 'eligible') {
          ready.push(task);  // pending + eligible → Ready
        } else {
          backlog.push(task);  // pending + manual_only/unassessed → Backlog
        }
        break;
      }
      case 'in_progress':
      case 'needs_work':
        inProgress.push(task);
        break;
      case 'pending_review':
        review.push(task);
        break;
      case 'completed':
        done.push(task);
        break;
      case 'blocked':
        inProgress.push(task);  // blocked → In Progress (shown with blocked indicator)
        break;
      case 'cancelled':
        done.push(task);  // cancelled → Done (shown with cancelled indicator)
        break;
    }
  }

  // Sort by priority (lower = higher)
  backlog.sort(byPriority);
  ready.sort(byPriority);
  inProgress.sort(byPriority);
  review.sort(byPriority);

  // Done: most recent first, limit to 20
  done.sort((a, b) => {
    const aTime = new Date(a.started_at || a.created_at).getTime();
    const bTime = new Date(b.started_at || b.created_at).getTime();
    return bTime - aTime;
  });
  const recentDone = done.slice(0, 20);

  return [
    { id: 'backlog', label: 'Backlog', tasks: backlog },
    { id: 'ready', label: 'Ready', tasks: ready },
    { id: 'in_progress', label: 'In Progress', tasks: inProgress },
    { id: 'review', label: 'Review', tasks: review },
    { id: 'done', label: 'Done', tasks: recentDone }
  ];
}
```

**Distribution is correct; it properly categorizes tasks by status and automation eligibility.**

