export async function fetchTasks(params?: {
  status?: string;
  type?: string;
  tag?: string;
  assignee?: string;
  automation?: string;
  plan?: string;
  limit?: number;
  offset?: number;
}): Promise<PaginatedResponse<TaskSummary>> {
  if (isStaticMode()) {
