 94→	async function loadBoard() {
 95→		loading = true;
 96→		error = '';
 97→		try {
 98→			const [taskResponse, statusResponse] = await Promise.all([
 99→				fetchTasks({ limit: 500 }),
100→				fetchAgentStatus().catch(() => null)
101→			]);
102→			tasks = taskResponse.items;
103→			agentStatus = statusResponse;
104→		} catch (err) {
105→			error = err instanceof Error ? err.message : 'Failed to load board';
106→		} finally {
107→			loading = false;
108→		}
109→	}
110→
111→	function handleCardClick(task: TaskSummary) {
112→		selectedTaskRef = task._ulid;
113→		modalOpen = true;
114→	}
115→
116→	function handleTaskUpdated() {
