    20→	Workflow,
    21→	PaginatedResponse,
    22→	SearchResponse,
    23→	SearchResult
    24→} from '@kynetic-ai/shared';
    25→import type { KspecSnapshot, ExportedTask, ExportedItem } from '$lib/types/snapshot';
    26→import { getSnapshot, ReadOnlyModeError } from '$lib/stores/mode.svelte';
    27→
    28→/**
    29→ * Convert ExportedTask to TaskSummary
    30→ */
    31→function toTaskSummary(task: ExportedTask): TaskSummary {
    32→	return {
    33→		_ulid: task._ulid,
    34→		slugs: task.slugs,
    35→		title: task.title,
    36→		type: task.type,
    37→		status: task.status,
    38→		priority: task.priority,
    39→		spec_ref: task.spec_ref ?? undefined,
    40→		tags: task.tags,
    41→		depends_on: task.depends_on,
    42→		created_at: task.created_at,
    43→		started_at: task.started_at ?? undefined,
    44→		notes_count: task.notes?.length ?? 0,
    45→		todos_count: task.todos?.length ?? 0
    46→	};
    47→}
    48→
    49→/**
    50→ * Convert ExportedItem to ItemSummary
    51→ */
    52→function toItemSummary(item: ExportedItem): ItemSummary {
    53→	return {
    54→		_ulid: item._ulid,
    55→		slugs: item.slugs,
    56→		title: item.title,
    57→		type: item.type,
    58→		status: item.status,
    59→		tags: item.tags,
    60→		created_at: item.created_at ?? new Date().toISOString()
    61→	};
    62→}
    63→
    64→/**
    65→ * Filter helper for tasks
    66→ */
    67→function filterTasks(
    68→	tasks: ExportedTask[],
    69→	params?: {
    70→		status?: string;
    71→		type?: string;
    72→		tag?: string;
    73→		assignee?: string;
    74→		automation?: string;
    75→	}
    76→): ExportedTask[] {
    77→	let result = tasks;
    78→
    79→	if (params?.status) {
    80→		result = result.filter((t) => t.status === params.status);
    81→	}
    82→	if (params?.type) {
    83→		result = result.filter((t) => t.type === params.type);
    84→	}
    85→	if (params?.tag) {
    86→		result = result.filter((t) => t.tags.includes(params.tag!));
    87→	}
    88→	if (params?.assignee) {
    89→		result = result.filter((t) => t.assignee === params.assignee);
    90→	}
    91→	if (params?.automation) {
    92→		result = result.filter((t) => t.automation === params.automation);
    93→	}
    94→
    95→	return result;
    96→}
    97→
    98→/**
    99→ * Filter helper for items
   100→ */
   101→function filterItems(
   102→	items: ExportedItem[],
   103→	params?: {
   104→		type?: string | string[];
   105→		tag?: string;
   106→	}
   107→): ExportedItem[] {
   108→	let result = items;
   109→
   110→	if (params?.type) {
   111→		const types = Array.isArray(params.type) ? params.type : [params.type];
   112→		result = result.filter((i) => types.includes(i.type));
   113→	}
   114→	if (params?.tag) {
   115→		result = result.filter((i) => i.tags.includes(params.tag!));
   116→	}
   117→
   118→	return result;
   119→}
   120→
   121→/**
   122→ * Paginate array
   123→ */
   124→function paginate<T>(
   125→	items: T[],
   126→	params?: { limit?: number; offset?: number }
   127→): PaginatedResponse<T> {
   128→	const limit = params?.limit ?? 50;
   129→	const offset = params?.offset ?? 0;
   130→	const paged = items.slice(offset, offset + limit);
   131→
   132→	return {
   133→		items: paged,
   134→		total: items.length,
   135→		offset,
   136→		limit
   137→	};
   138→}
   139→
   140→/**
   141→ * Find task by reference (slug or ULID prefix)
   142→ * AC: @gh-pages-export ac-12
   143→ */
   144→function findTaskByRef(tasks: ExportedTask[], ref: string): ExportedTask | null {
   145→	const normalizedRef = ref.startsWith('@') ? ref.slice(1) : ref;
   146→
   147→	// Try exact slug match first
   148→	const bySlug = tasks.find((t) => t.slugs.includes(normalizedRef));
   149→	if (bySlug) return bySlug;
   150→
   151→	// Try ULID prefix match
   152→	const byUlid = tasks.find((t) => t._ulid.startsWith(normalizedRef.toUpperCase()));
   153→	if (byUlid) return byUlid;
   154→
   155→	return null;
   156→}
   157→
   158→/**
   159→ * Find item by reference (slug or ULID prefix)
   160→ * AC: @gh-pages-export ac-13
   161→ */
   162→function findItemByRef(items: ExportedItem[], ref: string): ExportedItem | null {
   163→	const normalizedRef = ref.startsWith('@') ? ref.slice(1) : ref;
   164→
   165→	// Try exact slug match first
   166→	const bySlug = items.find((i) => i.slugs.includes(normalizedRef));
   167→	if (bySlug) return bySlug;
   168→
   169→	// Try ULID prefix match
   170→	const byUlid = items.find((i) => i._ulid.startsWith(normalizedRef.toUpperCase()));
   171→	if (byUlid) return byUlid;
   172→
   173→	return null;
   174→}
   175→
   176→// ============================================================
   177→// Static API Functions
   178→// ============================================================
   179→
   180→/**
   181→ * Fetch tasks from static snapshot
   182→ * AC: @gh-pages-export ac-11
   183→ */
   184→export function fetchTasksStatic(params?: {
   185→	status?: string;
   186→	type?: string;
   187→	tag?: string;
   188→	assignee?: string;
   189→	automation?: string;
   190→	limit?: number;
   191→	offset?: number;
   192→}): PaginatedResponse<TaskSummary> {
   193→	const snapshot = getSnapshot();
   194→	if (!snapshot) {
   195→		return { items: [], total: 0, offset: 0, limit: 50 };
   196→	}
   197→
   198→	const filtered = filterTasks(snapshot.tasks, params);
   199→	const paginated = paginate(filtered, params);
   200→
   201→	return {
   202→		...paginated,
   203→		items: paginated.items.map(toTaskSummary)
   204→	};
   205→}
   206→
   207→/**
   208→ * Fetch single task from static snapshot
   209→ * AC: @gh-pages-export ac-12
   210→ */
   211→export function fetchTaskStatic(ref: string): TaskDetail | null {
   212→	const snapshot = getSnapshot();
   213→	if (!snapshot) return null;
   214→
   215→	const task = findTaskByRef(snapshot.tasks, ref);
   216→	if (!task) return null;
   217→
   218→	// ExportedTask extends TaskDetail, so we can return it directly
   219→	return task;
   220→}
   221→
   222→/**
