   346→export function searchStatic(query: string): SearchResponse {
   347→	const snapshot = getSnapshot();
   348→	if (!snapshot) {
   349→		return { results: [], total: 0, showing: 0 };
   350→	}
   351→
   352→	const lowerQuery = query.toLowerCase();
   353→	const results: SearchResult[] = [];
   354→
   355→	// Search tasks
   356→	for (const task of snapshot.tasks) {
   357→		if (
   358→			task.title.toLowerCase().includes(lowerQuery) ||
   359→			task.slugs.some((s) => s.includes(lowerQuery))
   360→		) {
   361→			results.push({
   362→				type: 'task',
   363→				ulid: task._ulid,
   364→				title: task.title,
   365→				matchedFields: ['title']
   366→			});
   367→		}
   368→	}
   369→
   370→	// Search items
   371→	for (const item of snapshot.items) {
   372→		if (
   373→			item.title.toLowerCase().includes(lowerQuery) ||
   374→			item.slugs.some((s) => s.includes(lowerQuery))
   375→		) {
   376→			results.push({
   377→				type: 'item',
   378→				ulid: item._ulid,
   379→				title: item.title,
   380→				matchedFields: ['title']
   381→			});
   382→		}
   383→	}
   384→
   385→	// Search inbox
   386→	for (const inbox of snapshot.inbox) {
   387→		if (inbox.text.toLowerCase().includes(lowerQuery)) {
